interface SqlExecutor { int execute(String sql, Object... params) throws SQLException; }
class LoggingSqlExecutor implements SqlExecutor {
  private final SqlExecutor delegate;
  public int execute(String sql, Object... params) throws SQLException {
    long start = System.nanoTime();
    int result = delegate.execute(sql, params);
    logLine(sql, params, (System.nanoTime()-start)/1_000_000, result);
    return result;
  }
}

