record QueryLogEntry(String sql, long timeMs, int rows, boolean slow) {}
String toCsv(List<QueryLogEntry> entries) {
  StringBuilder csv = new StringBuilder("sql,timeMs,rows,slow\n");
  entries.forEach(e -> csv.append(e.sql()).append(",").append(e.timeMs()).append(",").append(e.rows()).append(",").append(e.slow()).append("\n"));
  return csv.toString();
}

